  1→import React, { memo, useCallback, useEffect, useState } from 'react';
  2→import { Button, Checkbox, Heading, Input, IconButton, Tabs, Text } from '@moego/ui';
  3→import { MajorCloseOutlined } from '@moego/icons-react';
  4→import type { AISchedulerData, AIQuickReplyData } from '../types';
  5→import {
  6→  DEFAULT_DEBUG_DATA,
  7→  DEFAULT_FULL_INTENT_REPLY_DEBUG_DATA,
  8→  DEFAULT_MISSING_INFO_DEBUG_DATA,
  9→} from './debug.mock';
 10→
 11→/** Debug 侧边栏 Props */
 12→interface MoeGoAISchedulerDebugSidebarProps {
 13→  /** 当前会话 customerId，用于自动注入调试 JSON */
 14→  customerId: number;
 15→  /** 是否打开 */
 16→  isOpen: boolean;
 17→  /** 模拟场景 */
 18→  onSimulateScenario: (data: AISchedulerData) => void;
 19→  /** 模拟 quick reply 场景 */
 20→  onSimulateQuickReply: (data: AIQuickReplyData) => void;
 21→  /** 重置 */
 22→  onReset: () => void;
 23→  /** 关闭 */
 24→  onClose: () => void;
 25→}
 26→
 27→const FULL_INTENT_OPTIONS = DEFAULT_FULL_INTENT_REPLY_DEBUG_DATA.quickReplyDirections ?? [];
 28→const DEFAULT_SELECTED_FULL_INTENT_LABELS = FULL_INTENT_OPTIONS.slice(0, 1).map((item) => item.label);
 29→
 30→function buildFullIntentReplyDebugData(
 31→  selectedLabels: string[],
 32→  baseData: AISchedulerData = DEFAULT_FULL_INTENT_REPLY_DEBUG_DATA,
 33→) {
 34→  return {
 35→    ...baseData,
 36→    quickReplyDirections: FULL_INTENT_OPTIONS.filter((item) => selectedLabels.includes(item.label)),
 37→  } satisfies AISchedulerData;
 38→}
 39→
 40→function withCustomerId(data: AISchedulerData, customerId: number): AISchedulerData {
 41→  return {
 42→    ...data,
 43→    customerId,
 44→  };
 45→}
 46→
 47→function replaceJsonCustomerId(json: string, customerId: number, fallback: AISchedulerData): string {
 48→  const parsed = (() => {
 49→    try {
 50→      return JSON.parse(json) as AISchedulerData;
 51→    } catch {
 52→      return fallback;
 53→    }
 54→  })();
 55→  return JSON.stringify(withCustomerId(parsed, customerId), null, 2);
 56→}
 57→
 58→/**
 59→ * MoeGo AI Scheduler 调试侧边栏
 60→ * - 仅在 URL 包含 aiSchedulerDebug=1 时显示
 61→ * - 固定在页面左侧
 62→ * - 允许手动触发 AI Scheduler 弹出
 63→ * - 允许修改调试数据
 64→ */
 65→export const MoeGoAISchedulerDebugSidebar = memo<MoeGoAISchedulerDebugSidebarProps>(
 66→  ({ customerId, isOpen, onSimulateScenario, onSimulateQuickReply, onReset, onClose }) => {
 67→    // JSON 编辑器内容（有 schedulingOptions - 展示 Scheduler）
 68→    const [jsonContent, setJsonContent] = useState(() =>
 69→      JSON.stringify(withCustomerId(DEFAULT_DEBUG_DATA, customerId), null, 2),
 70→    );
 71→
 72→    // Missing Info JSON 编辑器内容（有 missingFields/pendingUpdateFields - 展示 Missing Info）
 73→    const [missingInfoJsonContent, setMissingInfoJsonContent] = useState(
 74→      JSON.stringify(withCustomerId(DEFAULT_MISSING_INFO_DEBUG_DATA, customerId), null, 2),
 75→    );
 76→
 77→    // Full Intent Quick Replies JSON 编辑器内容（测试浮动 SMS Preview）
 78→    const [fullIntentReplyJsonContent, setFullIntentReplyJsonContent] = useState(
 79→      JSON.stringify(
 80→        buildFullIntentReplyDebugData(
 81→          DEFAULT_SELECTED_FULL_INTENT_LABELS,
 82→          withCustomerId(DEFAULT_FULL_INTENT_REPLY_DEBUG_DATA, customerId),
 83→        ),
 84→        null,
 85→        2,
 86→      ),
 87→    );
 88→
 89→    // Full Intent 勾选项（用于快速生成 quickReplyDirections）
 90→    const [selectedFullIntentLabels, setSelectedFullIntentLabels] = useState<string[]>(
 91→      DEFAULT_SELECTED_FULL_INTENT_LABELS,
 92→    );
 93→
 94→    // JSON 解析错误
 95→    const [jsonError, setJsonError] = useState<string | null>(null);
 96→
 97→    // 当前激活的 Tab
 98→    const [activeTab, setActiveTab] = useState<'scheduler' | 'missingInfo' | 'fullIntentReplies'>('scheduler');
 99→
100→    useEffect(() => {
101→      setJsonContent((prev) => replaceJsonCustomerId(prev, customerId, DEFAULT_DEBUG_DATA));
102→      setMissingInfoJsonContent((prev) => replaceJsonCustomerId(prev, customerId, DEFAULT_MISSING_INFO_DEBUG_DATA));
103→      setFullIntentReplyJsonContent((prev) =>
104→        replaceJsonCustomerId(
105→          prev,
106→          customerId,
107→          buildFullIntentReplyDebugData(
108→            DEFAULT_SELECTED_FULL_INTENT_LABELS,
109→            withCustomerId(DEFAULT_FULL_INTENT_REPLY_DEBUG_DATA, customerId),
110→          ),
111→        ),
112→      );
113→    }, [customerId]);
114→
115→    // 处理 JSON 内容变化
116→    const handleJsonChange = useCallback((value: string) => {
117→      setJsonContent(value);
118→      setJsonError(null);
119→    }, []);
120→
121→    // 处理 Missing Info JSON 内容变化
122→    const handleMissingInfoJsonChange = useCallback((value: string) => {
123→      setMissingInfoJsonContent(value);
124→      setJsonError(null);
125→    }, []);
126→
127→    // 处理 Full Intent Quick Replies JSON 内容变化
128→    const handleFullIntentReplyJsonChange = useCallback((value: string) => {
129→      setFullIntentReplyJsonContent(value);
130→      setJsonError(null);
131→    }, []);
132→
133→    const applyFullIntentSelection = useCallback(
134→      (nextLabels: string[]) => {
135→        setSelectedFullIntentLabels(nextLabels);
136→        const baseData = (() => {
137→          try {
138→            return JSON.parse(fullIntentReplyJsonContent) as AISchedulerData;
139→          } catch {
140→            return DEFAULT_FULL_INTENT_REPLY_DEBUG_DATA;
141→          }
142→        })();
143→        setFullIntentReplyJsonContent(JSON.stringify(buildFullIntentReplyDebugData(nextLabels, baseData), null, 2));
144→        setJsonError(null);
145→      },
146→      [fullIntentReplyJsonContent],
147→    );
148→
149→    // 重置为默认数据
150→    const handleReset = useCallback(() => {
151→      setJsonContent(JSON.stringify(withCustomerId(DEFAULT_DEBUG_DATA, customerId), null, 2));
152→      setMissingInfoJsonContent(JSON.stringify(withCustomerId(DEFAULT_MISSING_INFO_DEBUG_DATA, customerId), null, 2));
153→      setSelectedFullIntentLabels(DEFAULT_SELECTED_FULL_INTENT_LABELS);
154→      setFullIntentReplyJsonContent(
155→        JSON.stringify(
156→          buildFullIntentReplyDebugData(
157→            DEFAULT_SELECTED_FULL_INTENT_LABELS,
158→            withCustomerId(DEFAULT_FULL_INTENT_REPLY_DEBUG_DATA, customerId),
159→          ),
160→          null,
161→          2,
162→        ),
163→      );
164→      setJsonError(null);
165→      onReset();
166→    }, [customerId, onReset]);
167→
168→    // Debug 触发时注入唯一 contextUuid，避免与「关闭后 5 秒内忽略同 contextUuid」逻辑冲突，确保每次点击都会执行 processAISchedulerData
169→    const injectDebugContextUuid = useCallback((data: AISchedulerData): AISchedulerData => {
170→      return { ...data, contextUuid: `debug-${Date.now()}` };
171→    }, []);
172→
173→    // 触发 AI Scheduler（有 schedulingOptions）
174→    const handleTrigger = useCallback(() => {
175→      try {
176→        const data = injectDebugContextUuid(JSON.parse(jsonContent) as AISchedulerData);
177→        onSimulateScenario(data);
178→        setJsonError(null);
179→      } catch (error) {
180→        setJsonError(error instanceof Error ? error.message : 'Invalid JSON');
181→      }
182→    }, [jsonContent, onSimulateScenario, injectDebugContextUuid]);
183→
184→    // 触发 Missing Info 模拟（有 missingFields/pendingUpdateFields）
185→    const handleTriggerMissingInfo = useCallback(() => {
186→      try {
187→        const data = injectDebugContextUuid(JSON.parse(missingInfoJsonContent) as AISchedulerData);
188→        // 使用统一的 onSimulateScenario，前端会根据 schedulingOptions 是否存在来决定展示哪个面板
189→        onSimulateScenario(data);
190→        setJsonError(null);
191→      } catch (error) {
192→        setJsonError(error instanceof Error ? error.message : 'Invalid JSON');
193→      }
194→    }, [missingInfoJsonContent, onSimulateScenario, injectDebugContextUuid]);
195→
196→    // 触发 Full Intent Quick Replies 模拟（浮动 SMS Preview）
197→    const handleTriggerFullIntentReplies = useCallback(() => {
198→      try {
199→        const data = JSON.parse(fullIntentReplyJsonContent) as AISchedulerData;
200→        onSimulateQuickReply({
201→          customerId: data.customerId,
202→          quickReplyDirections: data.quickReplyDirections,
203→        });
204→        setJsonError(null);
205→      } catch (error) {
206→        setJsonError(error instanceof Error ? error.message : 'Invalid JSON');
207→      }
208→    }, [fullIntentReplyJsonContent, onSimulateQuickReply]);
209→
210→    if (!isOpen) {
211→      return null;
212→    }
213→
214→    return (
215→      <div className="moego-ai-scheduler-debug-sidebar moe-absolute moe-left-0 moe-top-0 moe-bottom-0 moe-w-[400px] moe-bg-white moe-border-r moe-border-divider moe-shadow-lg moe-z-[1000] moe-flex moe-flex-col">
216→        <div className="moe-flex moe-items-center moe-justify-between moe-px-4 moe-py-3 moe-border-b moe-border-divider">
217→          <div>
218→            <Heading size="3" className="moe-text-[16px] moe-font-semibold moe-text-primary moe-m-0">
219→              AI Scheduler Debug
220→            </Heading>
221→            <Text variant="caption" className="moe-text-secondary">
222→              Customer ID: {customerId}
223→            </Text>
224→          </div>
225→          <IconButton icon={<MajorCloseOutlined />} onPress={onClose} color="transparent" size="s" />
226→        </div>
227→
228→        {/* Tab 切换 */}
229→        <Tabs
230→          selectedKey={activeTab}
231→          onChange={(key) => setActiveTab(key as 'scheduler' | 'missingInfo' | 'fullIntentReplies')}
232→          enableMore
233→          classNames={{
234→            base: 'moe-mt-4',
235→            tabList: 'moe-px-4',
236→            panel: 'moe-px-4',
237→          }}
238→        >
239→          <Tabs.Item key="scheduler" label="With Scheduling Options">
240→            <Input.TextArea
241→              value={jsonContent}
242→              onChange={handleJsonChange}
243→              className="moe-flex-1 moe-font-mono moe-text-[12px] moe-min-h-[300px]"
244→              placeholder="Enter scheduler JSON data (with schedulingOptions)..."
245→            />
246→          </Tabs.Item>
247→          <Tabs.Item key="missingInfo" label="With Missing Fields">
248→            <Input.TextArea
249→              value={missingInfoJsonContent}
250→              onChange={handleMissingInfoJsonChange}
251→              className="moe-flex-1 moe-font-mono moe-text-[12px] moe-min-h-[300px]"
252→              placeholder="Enter scheduler JSON data (with missingFields/pendingUpdateFields)..."
253→            />
254→          </Tabs.Item>
255→          <Tabs.Item key="fullIntentReplies" label="With Full Intent Replies">
256→            <div className="moe-mb-3 moe-rounded-[8px] moe-border moe-border-divider moe-p-3">
257→              <Text variant="caption" className="moe-uppercase moe-mb-2 moe-block">
258→                Quick Intent Builder
259→              </Text>
260→
261→              <div className="moe-flex moe-flex-col moe-gap-2">
262→                <Checkbox
263→                  isSelected={
264→                    selectedFullIntentLabels.length === FULL_INTENT_OPTIONS.length && FULL_INTENT_OPTIONS.length > 0
265→                  }
266→                  isIndeterminate={
267→                    selectedFullIntentLabels.length > 0 && selectedFullIntentLabels.length < FULL_INTENT_OPTIONS.length
268→                  }
269→                  onChange={(checked) => {
270→                    if (checked) {
271→                      applyFullIntentSelection(FULL_INTENT_OPTIONS.map((item) => item.label));
272→                    } else {
273→                      applyFullIntentSelection([]);
274→                    }
275→                  }}
276→                >
277→                  All Intents
278→                </Checkbox>
279→
280→                {FULL_INTENT_OPTIONS.map((item) => (
281→                  <Checkbox
282→                    key={item.label}
283→                    isSelected={selectedFullIntentLabels.includes(item.label)}
284→                    onChange={() => {
285→                      const nextLabels = selectedFullIntentLabels.includes(item.label)
286→                        ? selectedFullIntentLabels.filter((label) => label !== item.label)
287→                        : [...selectedFullIntentLabels, item.label];
288→                      applyFullIntentSelection(nextLabels);
289→                    }}
290→                  >
291→                    {item.label}
292→                  </Checkbox>
293→                ))}
294→              </div>
295→            </div>
296→
297→            <Input.TextArea
298→              value={fullIntentReplyJsonContent}
299→              onChange={handleFullIntentReplyJsonChange}
300→              className="moe-flex-1 moe-font-mono moe-text-[12px] moe-min-h-[300px]"
301→              placeholder="Enter scheduler JSON data (with quickReplyDirections)..."
302→            />
303→          </Tabs.Item>
304→        </Tabs>
305→
306→        {jsonError && (
307→          <div className="moe-mb-3 moe-p-2 moe-bg-red-50 moe-border moe-border-red-200 moe-rounded moe-text-[12px] moe-text-red-600">
308→            {jsonError}
309→          </div>
310→        )}
311→
312→        {activeTab === 'scheduler' && (
313→          <div className="moe-flex moe-gap-2 moe-mx-4 moe-my-4 moe-mt-auto">
314→            <Button variant="secondary" size="s" onPress={handleReset} className="moe-flex-1">
315→              Reset
316→            </Button>
317→            <Button variant="primary" size="s" onPress={handleTrigger} className="moe-flex-1">
318→              Trigger Scheduler
319→            </Button>
320→          </div>
321→        )}
322→
323→        {activeTab === 'missingInfo' && (
324→          <div className="moe-flex moe-gap-2 moe-mx-4 moe-my-4 moe-mt-auto">
325→            <Button variant="secondary" size="s" onPress={handleReset} className="moe-flex-1">
326→              Reset
327→            </Button>
328→            <Button variant="primary" size="s" onPress={handleTriggerMissingInfo} className="moe-flex-1">
329→              Trigger Missing Info
330→            </Button>
331→          </div>
332→        )}
333→
334→        {activeTab === 'fullIntentReplies' && (
335→          <div className="moe-flex moe-gap-2 moe-mx-4 moe-my-4 moe-mt-auto">
336→            <Button variant="secondary" size="s" onPress={handleReset} className="moe-flex-1">
337→              Reset
338→            </Button>
339→            <Button variant="primary" size="s" onPress={handleTriggerFullIntentReplies} className="moe-flex-1">
340→              Trigger Full Intent Replies
341→            </Button>
342→          </div>
343→        )}
344→      </div>
345→    );
346→  },
347→);
348→
349→MoeGoAISchedulerDebugSidebar.displayName = 'MoeGoAISchedulerDebugSidebar';
