 1→import React, { memo } from 'react';
 2→import { Button } from '@moego/ui';
 3→
 4→/** Debug 按钮 Props */
 5→interface MoeGoAISchedulerDebugButtonProps {
 6→  /** 点击 */
 7→  onPress: () => void;
 8→}
 9→
10→/**
11→ * MoeGo AI Scheduler 调试按钮
12→ * - 仅在 URL query 包含调试参数时显示
13→ * - 放置于 AssistantList 中，在 AI assist 按钮后面
14→ */
15→export const MoeGoAISchedulerDebugButton = memo<MoeGoAISchedulerDebugButtonProps>(({ onPress }) => {
16→  return (
17→    <Button variant="tertiary" size="s" onPress={onPress}>
18→      [DEV] Debug AI Scheduler
19→    </Button>
20→  );
21→});
22→
23→MoeGoAISchedulerDebugButton.displayName = 'MoeGoAISchedulerDebugButton';
24→

 1→import React, { createContext, useContext, useMemo } from 'react';
 2→
 3→interface MoeGoAISchedulerDebugContextValue {
 4→  /** 是否显示调试功能 */
 5→  isDebugMode: boolean;
 6→  /** 打开调试面板 */
 7→  openDebugPanel: () => void;
 8→}
 9→
10→const MoeGoAISchedulerDebugContext = createContext<MoeGoAISchedulerDebugContextValue | null>(null);
11→
12→interface MoeGoAISchedulerDebugProviderProps {
13→  isDebugMode: boolean;
14→  openDebugPanel: () => void;
15→  children: React.ReactNode;
16→}
17→
18→/**
19→ * AI Scheduler Debug Context Provider
20→ * 为子组件提供调试功能的开关和回调
21→ */
22→export const MoeGoAISchedulerDebugProvider: React.FC<MoeGoAISchedulerDebugProviderProps> = ({
23→  isDebugMode,
24→  openDebugPanel,
25→  children,
26→}) => {
27→  const value = useMemo(
28→    () => ({
29→      isDebugMode,
30→      openDebugPanel,
31→    }),
32→    [isDebugMode, openDebugPanel],
33→  );
34→
35→  return <MoeGoAISchedulerDebugContext.Provider value={value}>{children}</MoeGoAISchedulerDebugContext.Provider>;
36→};
37→
38→/**
39→ * 获取 AI Scheduler Debug Context
40→ * 如果不在 Provider 内部，返回默认值（非调试模式）
41→ */
42→export const useMoeGoAISchedulerDebug = (): MoeGoAISchedulerDebugContextValue => {
43→  const context = useContext(MoeGoAISchedulerDebugContext);
44→  if (!context) {
45→    return {
46→      isDebugMode: false,
47→      openDebugPanel: () => {},
48→    };
49→  }
50→  return context;
51→};
