  1→import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
  2→import { useDispatch } from 'amos';
  3→import { sendMessageToCustomer } from '../../../../../store/message/message.actions';
  4→import { PUSH_OPEN_AI_SCHEDULER, PUSH_OPEN_QUICK_REPLY } from '../../../../../router/paths';
  5→import { toastApi } from '../../../../../components/Toast/Toast';
  6→import { enqueueSignal, SmsAgentSignalType } from './api';
  7→import { normalizeAISchedulerData } from './utils';
  8→import { useAnimationTrigger } from './useAnimationTrigger';
  9→import type { MoegoWs } from '../../../../../utils/MoegoWs';
 10→import type { AISchedulerData, AIQuickReplyData, SchedulerLoadingState } from './types';
 11→
 12→interface UseAISchedulerParams {
 13→  customerId: number;
 14→  staffId: number;
 15→  /** WebSocket instance from useWs() */
 16→  ws: MoegoWs | null | undefined;
 17→  /** Feature flag: sms-agent */
 18→  enabled?: boolean;
 19→  /** Feature flag: sms-agent-draft */
 20→  quickReplyEnabled?: boolean;
 21→}
 22→
 23→const CONTEXT_IGNORE_WINDOW_MS = 5_000;
 24→
 25→/**
 26→ * 封装 AI Scheduler 所有状态管理、WebSocket 监听和交互回调。
 27→ * 组件渲染仍由 MessageCenter 负责，本 hook 仅提供数据与 handler。
 28→ */
 29→export function useAIScheduler({
 30→  customerId,
 31→  staffId,
 32→  ws,
 33→  enabled = true,
 34→  quickReplyEnabled = true,
 35→}: UseAISchedulerParams) {
 36→  const dispatch = useDispatch();
 37→
 38→  // AI Scheduler 面板状态
 39→  const [aiSchedulerVisible, setAISchedulerVisible] = useState(false);
 40→  const [aiSchedulerData, setAISchedulerData] = useState<AISchedulerData | null>(null);
 41→  // Floating SMS Preview 独立状态（与面板显隐解耦）
 42→  const [aiSchedulerQuickReplyDirections, setAISchedulerQuickReplyDirections] = useState<
 43→    AISchedulerData['quickReplyDirections']
 44→  >([]);
 45→  const [aiSchedulerDebugOpen, setAISchedulerDebugOpen] = useState(false);
 46→  const [aiSchedulerLoadingState, setAISchedulerLoadingState] = useState<SchedulerLoadingState>('idle');
 47→  const { isActive: dataUpdateAnimationActive, trigger: triggerDataUpdateAnimation } = useAnimationTrigger({
 48→    durationMs: 1000,
 49→  });
 50→
 51→  // 用于在 WS handler 中判断面板是否已可见且已有数据
 52→  const visibleRef = useRef(false);
 53→  const dataRef = useRef<AISchedulerData | null>(null);
 54→  const previousVisibleRef = useRef(false);
 55→  const ignoredContextUuidsRef = useRef<Map<string, number>>(new Map());
 56→  const pendingManualContextUuidRef = useRef<string | null>(null);
 57→
 58→  const shouldIgnoreContextUuid = useCallback((contextUuid: string) => {
 59→    const ignoredAt = ignoredContextUuidsRef.current.get(contextUuid);
 60→    if (!ignoredAt) {
 61→      return false;
 62→    }
 63→    const withinIgnoreWindow = Date.now() - ignoredAt < CONTEXT_IGNORE_WINDOW_MS;
 64→    if (!withinIgnoreWindow) {
 65→      ignoredContextUuidsRef.current.delete(contextUuid);
 66→    }
 67→    return withinIgnoreWindow;
 68→  }, []);
 69→  useEffect(() => {
 70→    visibleRef.current = aiSchedulerVisible;
 71→  }, [aiSchedulerVisible]);
 72→  useEffect(() => {
 73→    dataRef.current = aiSchedulerData;
 74→  }, [aiSchedulerData]);
 75→
 76→  useEffect(() => {
 77→    const wasVisible = previousVisibleRef.current;
 78→    if (wasVisible && !aiSchedulerVisible) {
 79→      const currentContextUuid = dataRef.current?.contextUuid;
 80→      if (currentContextUuid) {
 81→        ignoredContextUuidsRef.current.set(currentContextUuid, Date.now());
 82→      }
 83→      if (pendingManualContextUuidRef.current) {
 84→        ignoredContextUuidsRef.current.set(pendingManualContextUuidRef.current, Date.now());
 85→      }
 86→    }
 87→    previousVisibleRef.current = aiSchedulerVisible;
 88→  }, [aiSchedulerVisible]);
 89→
 90→  // 切换 customer 时关闭 AI Scheduler，避免数据串联
 91→  useEffect(() => {
 92→    setAISchedulerVisible(false);
 93→    setAISchedulerData(null);
 94→    setAISchedulerQuickReplyDirections([]);
 95→    setAISchedulerLoadingState('idle');
 96→    ignoredContextUuidsRef.current.clear();
 97→    pendingManualContextUuidRef.current = null;
 98→  }, [customerId]);
 99→
100→  // Feature flag 关闭时，确保所有 AI Scheduler 状态复位
101→  useEffect(() => {
102→    if (enabled) return;
103→    setAISchedulerVisible(false);
104→    setAISchedulerData(null);
105→    setAISchedulerQuickReplyDirections([]);
106→    setAISchedulerDebugOpen(false);
107→    setAISchedulerLoadingState('idle');
108→    ignoredContextUuidsRef.current.clear();
109→    pendingManualContextUuidRef.current = null;
110→  }, [enabled]);
111→
112→  useEffect(() => {
113→    if (quickReplyEnabled) return;
114→    setAISchedulerQuickReplyDirections([]);
115→  }, [quickReplyEnabled]);
116→
117→  // 统一处理来自 WS / Debug 的 AIScheduler 数据
118→  const processAISchedulerData = useCallback(
119→    (incoming: unknown) => {
120→      const data = incoming as AISchedulerData;
121→      if (data.customerId && String(data.customerId) !== String(customerId)) {
122→        return;
123→      }
124→
125→      if (data.contextUuid && shouldIgnoreContextUuid(data.contextUuid)) {
126→        return;
127→      }
128→
129→      if (data.contextUuid && pendingManualContextUuidRef.current === data.contextUuid) {
130→        pendingManualContextUuidRef.current = null;
131→      }
132→
133→      const normalizedData = normalizeAISchedulerData(data);
134→
135→      if (visibleRef.current && dataRef.current) {
136→        // 面板已可见且已有数据时，标记为"数据更新"以触发通知动画
137→        triggerDataUpdateAnimation();
138→      }
139→      setAISchedulerData(normalizedData);
140→      setAISchedulerVisible(true);
141→    },
142→    [customerId, shouldIgnoreContextUuid, triggerDataUpdateAnimation],
143→  );
144→
145→  const processQuickReplyData = useCallback(
146→    (incoming: unknown) => {
147→      if (!quickReplyEnabled) {
148→        return;
149→      }
150→
151→      const data = incoming as AIQuickReplyData;
152→
153→      if (data.customerId && String(data.customerId) !== String(customerId)) {
154→        return;
155→      }
156→
157→      const directions = data.quickReplyDirections ?? [];
158→      setAISchedulerQuickReplyDirections(directions);
159→    },
160→    [customerId, quickReplyEnabled],
161→  );
162→
163→  // AI Scheduler WebSocket 监听
164→  useEffect(() => {
165→    if (!enabled) {
166→      return;
167→    }
168→    const offAIScheduler = ws?.handlePush(PUSH_OPEN_AI_SCHEDULER, processAISchedulerData);
169→    return () => {
170→      offAIScheduler?.();
171→    };
172→  }, [ws, customerId, enabled, processAISchedulerData]);
173→
174→  useEffect(() => {
175→    if (!quickReplyEnabled) {
176→      return;
177→    }
178→    const offQuickReply = ws?.handlePush(PUSH_OPEN_QUICK_REPLY, processQuickReplyData);
179→    return () => {
180→      offQuickReply?.();
181→    };
182→  }, [ws, customerId, quickReplyEnabled, processQuickReplyData]);
183→
184→  // AI Scheduler 发送消息回调
185→  const handleAISchedulerSendMessage = useCallback(
186→    async (message: string) => {
187→      await dispatch(sendMessageToCustomer(customerId, message));
188→      setAISchedulerQuickReplyDirections([]);
189→    },
190→    [dispatch, customerId],
191→  );
192→
193→  const handleAISchedulerDismissQuickReply = useCallback(() => {
194→    setAISchedulerQuickReplyDirections([]);
195→  }, []);
196→
197→  // AI Scheduler 手动触发
198→  const handleAISchedulerTrigger = useCallback(async () => {
199→    if (!enabled) {
200→      return Promise.resolve();
201→    }
202→    // 立即显示面板
203→    setAISchedulerVisible(true);
204→    setAISchedulerLoadingState('loading');
205→
206→    // 通知后端用户加入对话，触发 AI Scheduler WebSocket 推送
207→    try {
208→      const response = await enqueueSignal({
209→        customerId: String(customerId),
210→        staffId: String(staffId),
211→        signalType: SmsAgentSignalType.JOIN_CONVERSATION,
212→      });
213→
214→      const responseContextUuid = response?.contextUuid;
215→      if (!responseContextUuid) {
216→        return;
217→      }
218→
219→      if (visibleRef.current) {
220→        pendingManualContextUuidRef.current = responseContextUuid;
221→      } else {
222→        ignoredContextUuidsRef.current.set(responseContextUuid, Date.now());
223→      }
224→    } catch {
225→      pendingManualContextUuidRef.current = null;
226→      setAISchedulerData(null);
227→      setAISchedulerVisible(false);
228→      setAISchedulerLoadingState('idle');
229→      toastApi.error('Failed to trigger AI Scheduler');
230→    }
231→  }, [customerId, staffId, enabled]);
232→
233→  // AI Scheduler 调试触发
234→  const handleAISchedulerDebugTrigger = processAISchedulerData;
235→  const handleAISchedulerQuickReplyDebugTrigger = processQuickReplyData;
236→
237→  const handleAISchedulerCloseAndReset = useCallback(() => {
238→    setAISchedulerData(null);
239→    setAISchedulerLoadingState('idle');
240→    setAISchedulerVisible(false);
241→  }, []);
242→
243→  // AI Scheduler 调试重置
244→  const handleAISchedulerDebugReset = useCallback(() => {
245→    setAISchedulerData(null);
246→    setAISchedulerQuickReplyDirections([]);
247→    setAISchedulerVisible(false);
248→    setAISchedulerLoadingState('idle');
249→  }, []);
250→
251→  // AI Scheduler 调试关闭
252→  const handleAISchedulerDebugClose = useCallback(() => {
253→    setAISchedulerDebugOpen(false);
254→  }, []);
255→
256→  // AI Scheduler 调试打开
257→  const handleAISchedulerDebugOpen = useCallback(() => {
258→    setAISchedulerDebugOpen(true);
259→  }, []);
260→
261→  // 检查是否为调试模式
262→  const isAISchedulerDebugMode = useMemo(() => {
263→    if (!enabled) return false;
264→    if (typeof window === 'undefined') return false;
265→    const params = new URLSearchParams(window.location.search);
266→    return params.get('aiSchedulerDebug') === '1';
267→  }, [enabled]);
268→
269→  return {
270→    // State
271→    aiSchedulerVisible,
272→    setAISchedulerVisible,
273→    aiSchedulerData,
274→    aiSchedulerQuickReplyDirections,
275→    aiSchedulerLoadingState,
276→    /** WebSocket 推送新数据时触发的更新通知标记，用于驱动面板高亮动画 */
277→    aiSchedulerDataUpdated: dataUpdateAnimationActive,
278→
279→    // Debug state
280→    aiSchedulerDebugOpen,
281→    isAISchedulerDebugMode,
282→
283→    // Handlers
284→    handleAISchedulerSendMessage,
285→    handleAISchedulerDismissQuickReply,
286→    handleAISchedulerTrigger,
287→    handleAISchedulerCloseAndReset,
288→    handleAISchedulerDebugTrigger,
289→    handleAISchedulerQuickReplyDebugTrigger,
290→    handleAISchedulerDebugReset,
291→    handleAISchedulerDebugClose,
292→    handleAISchedulerDebugOpen,
293→  };
294→}
