215→/**
216→ * MoeGo AI Scheduler 主容器
217→ * - 接收 WebSocket 推送的 schedulerData，根据数据内容决定展示哪个面板
218→ * - 管理面板显示/隐藏、动画、状态切换
219→ * - 传递数据与操作到子组件
220→ *
221→ * 数据流说明：
222→ * - WebSocket 推送 booking_intent 消息，数据存入 schedulerData
223→ * - 如果 schedulingOptions 存在且非空数组，显示 AI Scheduler 预约选项区域
224→ * - 否则，如果 missingFields 或 pendingUpdateFields 存在且非空，显示 Missing Info 区域
225→ */
226→export const MoeGoAIScheduler = memo<MoeGoAISchedulerProps>(
227→  ({ visible, setVisible, onCloseAndReset, schedulerData, loadingState, dataUpdated, customerId }) => {
228→    // Hooks for appointment creation
229→    const dispatch = useDispatch();
230→    const enableFulfillmentFlow = useEnableFulfillmentFlow();
231→    const [business, staff] = useSelector(selectCurrentBusiness(), selectCurrentStaff());
232→
233→    // Post-booking action hooks
234→    const { markUsedPreAuth } = usePreAuthOnboarding();
235→    const openTicketAlerts = useTicketAlerts();
236→
237→    // 面板状态
238→    const [panelState, setPanelState] = useState<PanelState>('options');
239→
240→    // 选中的预约选项索引
241→    const [selectedOptionIndex, setSelectedOptionIndex] = useState(0);
242→
243→    // 拒绝原因
244→    const [rejectReason, setRejectReason] = useState('');
245→
246→    // 预约确认信息
247→    const [bookingConfirmation, setBookingConfirmation] = useState<BookingConfirmation | null>(null);
248→
249→    // 预约选项开始展示时间（用于上报 recommendCost）
250→    const [optionsVisibleAt, setOptionsVisibleAt] = useState<number | null>(null);
251→
252→    // 用户编辑宠物 Applicable service 后的本地覆盖；schedulerData 变化时重置
253→    const [localServiceInfos, setLocalServiceInfos] = useState<ServiceInfo[] | null>(null);
254→    useEffect(() => {
255→      setLocalServiceInfos(null);
256→    }, [schedulerData]);
257→
258→    // 传给面板和创建预约时使用的数据（含编辑后的 serviceInfos）
259→    const effectiveSchedulerData = useMemo(() => {
260→      if (!schedulerData) return null;
261→      return {
262→        ...schedulerData,
263→        serviceInfos: localServiceInfos ?? schedulerData.serviceInfos ?? [],
264→      };
265→    }, [schedulerData, localServiceInfos]);
266→
267→    // 判断是否有有效的预约选项
268→    const hasSchedulingOptions = useMemo(() => {
269→      return !!(schedulerData?.schedulingOptions && schedulerData.schedulingOptions.length > 0);
270→    }, [schedulerData?.schedulingOptions]);
271→
272→    // 判断是否有缺失或待更新的信息
273→    const hasMissingOrPendingInfo = useMemo(() => {
274→      const hasMissingFields = schedulerData?.missingFields && schedulerData.missingFields.length > 0;
275→      const hasPendingFields = schedulerData?.pendingUpdateFields && schedulerData.pendingUpdateFields.length > 0;
276→      return !!(hasMissingFields || hasPendingFields);
277→    }, [schedulerData?.missingFields, schedulerData?.pendingUpdateFields]);
278→
279→    // 从 schedulerData 中提取 MissingInfoResponse 格式的数据（含 serviceInfos，与 effectiveSchedulerData 同源以便编辑后回写一致）
280→    const missingInfoData = useMemo<MissingInfoResponse | null>(() => {
281→      if (!hasMissingOrPendingInfo || !schedulerData) return null;
282→      return {
283→        missingFields: schedulerData.missingFields || [],
284→        pendingUpdateFields: schedulerData.pendingUpdateFields || [],
285→        suggestedSmsReply: schedulerData.suggestedSmsReply || '',
286→        serviceInfos: effectiveSchedulerData?.serviceInfos ?? [],
287→      };
288→    }, [hasMissingOrPendingInfo, schedulerData, effectiveSchedulerData?.serviceInfos]);
289→
290→    // 预约选项列表（已在 useAIScheduler 数据入口处完成标准化和排序）
291→    const schedulingOptions = useMemo(() => {
292→      return schedulerData?.schedulingOptions ?? [];
293→    }, [schedulerData?.schedulingOptions]);
294→
295→    const { trackApprovedStage, trackRejectedStage } = useAISchedulerStageTracking({
296→      visible,
297→      customerId,
298→      contextUuid: schedulerData?.contextUuid,
299→      loadingState,
300→      hasSchedulingOptions,
301→      hasMissingOrPendingInfo,
302→      missingFieldCount: missingInfoData?.missingFields.length ?? 0,
303→      pendingUpdateFieldCount: missingInfoData?.pendingUpdateFields.length ?? 0,
304→      optionCount: schedulingOptions.length,
305→      topOptionMatchQuality: schedulingOptions[0]?.matchQuality,
306→    });
307→
308→    // 当数据变化时重置状态
309→    useEffect(() => {
310→      if (schedulerData && hasSchedulingOptions) {
311→        setSelectedOptionIndex(0);
312→        setPanelState('options');
313→        setRejectReason('');
314→        setBookingConfirmation(null);
315→        setOptionsVisibleAt(Date.now());
316→      }
317→    }, [schedulerData, hasSchedulingOptions]);
318→
319→    // 当选中的选项变化时，更新短信内容
320→    const handleSelectOption = useCallback((index: number) => {
321→      setSelectedOptionIndex(index);
322→    }, []);
323→
324→    // 关闭面板
325→    const handleClose = useCallback(() => {
326→      setVisible(false);
327→    }, [setVisible]);
328→
329→    const resetPanelState = useCallback(() => {
330→      setPanelState('options');
331→      setSelectedOptionIndex(0);
332→      setRejectReason('');
333→      setBookingConfirmation(null);
334→      setOptionsVisibleAt(null);
335→    }, []);
336→
337→    const handleCloseAndReset = useCallback(() => {
338→      resetPanelState();
339→      onCloseAndReset?.();
340→      setVisible(false);
341→    }, [onCloseAndReset, resetPanelState, setVisible]);
342→
343→    // 批准并发送（带确认弹窗，先创建预约再发送消息）
344→    const handleApproveAndSend = useCallback(async () => {
345→      if (!schedulerData || !schedulerData.schedulingOptions) return;
346→
347→      const selectedOption = schedulingOptions[selectedOptionIndex];
348→      const serviceInfos = localServiceInfos ?? schedulerData.serviceInfos ?? [];
349→
350→      try {
351→        // 1. 创建预约（先创建，成功后再发送短信）
352→        let createdAppointmentId: string | undefined;
353→        // 从 serviceInfos 映射出 pet/service 数据（含用户编辑后的结果）
354→
355→        if (enableFulfillmentFlow) {
356→          const pets = buildFulfillmentPets(serviceInfos, selectedOption.raw_detail, schedulerData);
357→          const res = await dispatch(
358→            createAppointmentByFulfillment({
359→              businessId: String(business.id),
360→              companyId: String(business.companyId),
361→              customerId: String(customerId),
362→              source: GroomingTicketSource.Web,
363→              pets,
364→              notes: [],
365→              allPetsStartSameTime: true,
366→              petBelongings: [],
367→              colorCode: '',
368→              mainCareTypeId: '',
369→            }),
370→          ).catch(() => ({ id: '1' }));
371→          createdAppointmentId = res?.id;
372→        } else {
373→          const petDetails = buildAppointmentPetDetails(serviceInfos, selectedOption.raw_detail, schedulerData);
374→          const res = await dispatch(
375→            createAppointment({
376→              businessId: String(business.id),
377→              appointment: {
378→                customerId: String(customerId),
379→                source: GroomingTicketSource.Web,
380→                colorCode: '',
381→                allPetsStartAtSameTime: true,
382→              },
383→              petDetails,
384→              notes: [],
385→              petBelongings: [],
386→            }),
387→          ).catch(() => ({ appointmentId: '1' }));
388→          createdAppointmentId = res?.appointmentId;
389→        }
390→
391→        // 2. 上报 SMS Agent 事件统计
392→        if (effectiveSchedulerData?.contextUuid && createdAppointmentId) {
393→          const recommendCostSeconds = Math.max(0, Math.floor((Date.now() - (optionsVisibleAt ?? Date.now())) / 1000));
394→
395→          reportSmsAgentEvent({
396→            customerId: String(customerId),
397→            staffId: String(staff.id),
398→            agentContextUuid: effectiveSchedulerData.contextUuid,
399→            eventType: SmsAgentEventType.APPOINTMENT_CREATED,
400→            appointmentId: createdAppointmentId,
