434→        globalEvent.createdAppt.emit({ apptId: String(ticketId) });
435→
436→        // 4. 切换到确认页
437→        setBookingConfirmation({
438→          time: selectedOption.time,
439→          date: selectedOption.date,
440→          groomerName: selectedOption.groomerName,
441→          steps: {
442→            appointmentBooked: true,
443→            confirmationMessageSent: false,
444→          },
445→          appointmentId: createdAppointmentId,
446→        });
447→        setPanelState('confirmation');
448→
449→        toast({ type: 'success', title: 'Appointment created successfully' });
450→      } catch {
451→        toast({ type: 'error', title: 'Failed to confirm and book' });
452→      }
453→    }, [
454→      schedulerData,
455→      localServiceInfos,
456→      effectiveSchedulerData,
457→      selectedOptionIndex,
458→      schedulingOptions,
459→      dispatch,
460→      enableFulfillmentFlow,
461→      business,
462→      staff,
463→      customerId,
464→      markUsedPreAuth,
