469→
470→    // 拒绝
471→    const handleReject = useCallback(() => {
472→      setPanelState('reject');
473→    }, []);
474→
475→    // 确认拒绝
476→    const handleConfirmReject = useCallback(async () => {
477→      const feedbackContent = rejectReason.trim() || 'N/A';
478→
479→      // 上报反馈事件
