488→          });
489→
490→          trackRejectedStage({
491→            feedbackLength: feedbackContent.length,
492→            hasFeedbackInput: feedbackContent !== 'N/A',
493→            feedbackSource: 'drawer',
494→          });
495→
496→          toast({ type: 'success', title: 'Your feedback has been submitted.' });
497→          handleCloseAndReset();
498→        } catch {
499→          toast({ type: 'error', title: 'Failed to submit feedback, please try again.' });
500→        }
501→      }
502→    }, [handleCloseAndReset, schedulerData?.contextUuid, customerId, rejectReason, staff, trackRejectedStage]);
503→
504→    // 从拒绝页返回
505→    const handleBackFromReject = useCallback(() => {
506→      setPanelState('options');
507→    }, []);
508→
509→    // 默认的预约确认信息（用于确认页兜底）
510→    const defaultBookingConfirmation = useMemo<BookingConfirmation>(() => {
511→      if (bookingConfirmation) return bookingConfirmation;
512→      const selectedOption = schedulingOptions[selectedOptionIndex];
513→      return {
514→        time: selectedOption?.time || '',
515→        date: selectedOption?.date || '',
516→        groomerName: selectedOption?.groomerName || '',
517→        steps: {
518→          appointmentBooked: true,
519→          confirmationMessageSent: true,
520→        },
521→      };
522→    }, [bookingConfirmation, schedulingOptions, selectedOptionIndex]);
523→
524→    useEffect(() => {
525→      if (visible) return;
526→      if (schedulerData) return;
527→      resetPanelState();
528→    }, [visible, schedulerData, resetPanelState]);
529→
530→    if (!visible) {
531→      return null;
532→    }
533→
534→    // 手动触发后等待后端响应：展示意图识别中的友好提示（非 loading 态）
535→    if (loadingState === 'loading' && !schedulerData) {
536→      return (
537→        <PanelWrapper visible={visible}>
538→          <RecognizingIntentContent onClose={handleClose} />
539→        </PanelWrapper>
540→      );
541→    }
542→
543→    // 缺失信息状态（没有预约选项，但有缺失/待更新信息）
544→    if (!hasSchedulingOptions && missingInfoData) {
545→      return (
546→        <PanelWrapper visible={visible}>
547→          <MissingInfoPanelContent
548→            data={missingInfoData}
549→            onClose={handleClose}
550→            customerId={customerId}
551→            dataUpdated={dataUpdated}
552→            contextUuid={effectiveSchedulerData?.contextUuid}
553→            onServiceInfosChange={setLocalServiceInfos}
554→          />
555→        </PanelWrapper>
556→      );
557→    }
558→
559→    // 有调度数据且有预约选项时展示主面板
560→    if (schedulerData && hasSchedulingOptions) {
561→      return (
562→        <PanelWrapper visible={visible}>
563→          <SchedulerPanelContent
564→            data={effectiveSchedulerData ?? schedulerData ?? ({} as AISchedulerData)}
565→            panelState={panelState}
566→            selectedOptionIndex={selectedOptionIndex}
567→            rejectReason={rejectReason}
568→            bookingConfirmation={defaultBookingConfirmation}
569→            dataUpdated={dataUpdated}
570→            onSelectOption={handleSelectOption}
571→            onApprove={handleApproveAndSend}
572→            onReject={handleReject}
573→            onReasonChange={setRejectReason}
574→            onConfirmReject={handleConfirmReject}
575→            onBackFromReject={handleBackFromReject}
576→            onDone={handleCloseAndReset}
577→            onClose={handleClose}
578→            onServiceInfosChange={setLocalServiceInfos}
579→          />
580→        </PanelWrapper>
581→      );
582→    }
583→
584→    // 有推送数据，但没有 options / missing / pending 时，展示积极语气的无结果页
585→    if (schedulerData) {
586→      return (
587→        <PanelWrapper visible={visible}>
588→          <NoResultContent onClose={handleClose} />
589→        </PanelWrapper>
590→      );
591→    }
592→
593→    return null;
594→  },
595→);
